import { IncomingMessage } from 'http';
import { Observable } from 'rxjs';
import { CONTROLLER_ID_KEY } from '../injector/constants.js';
import { ContextId } from '../injector/instance-wrapper.js';
import { HeaderStream } from '../router/sse-stream.js';
import { ParamProperties } from './context-utils.js';
import type { Type } from '@nestjs/common';
import type { Controller } from '@nestjs/common/internal';

export const HANDLER_METADATA_SYMBOL = Symbol.for('handler_metadata:cache');

export type HandleResponseFn = HandlerResponseBasicFn | HandleSseResponseFn;

export type HandlerResponseBasicFn = <TResult, TResponse>(
  result: TResult,
  res: TResponse,
  req?: any,
) => any;

export type HandleSseResponseFn = <
  TResult extends Observable<unknown> = any,
  TResponse extends HeaderStream = any,
  TRequest extends IncomingMessage = any,
>(
  result: TResult,
  res: TResponse,
  req: TRequest,
) => any;

export interface HandlerMetadata {
  argsLength: number;
  isSseHandler: boolean;
  paramtypes: any[];
  httpStatusCode: number;
  responseHeaders: any[];
  hasCustomHeaders: boolean;
  aggregateParamErrors: boolean;
  getParamsMetadata: (
    moduleKey: string,
    contextId?: ContextId,
    inquirerId?: string,
  ) => (ParamProperties & { metatype?: any })[];
  fnHandleResponse: HandleResponseFn;
}

export class HandlerMetadataStorage<
  TValue = HandlerMetadata,
  TKey extends Type<unknown> = any,
> {
  private readonly [HANDLER_METADATA_SYMBOL] = new Map<string, TValue>();

  set(controller: TKey, methodName: string, metadata: TValue) {
    const metadataKey = this.getMetadataKey(controller, methodName);
    this[HANDLER_METADATA_SYMBOL].set(metadataKey, metadata);
  }

  get(controller: TKey, methodName: string): TValue | undefined {
    const metadataKey = this.getMetadataKey(controller, methodName);
    return this[HANDLER_METADATA_SYMBOL].get(metadataKey);
  }

  private getMetadataKey(controller: Controller, methodName: string): string {
    const ctor = controller.constructor;
    const controllerKey = ctor && (ctor[CONTROLLER_ID_KEY] || ctor.name);
    return controllerKey + methodName;
  }
}

import { AGGREGATE_PARAM_ERRORS_METADATA } from '../../constants.js';

/**
 * Request method Decorator. Aggregates validation errors thrown by the pipes
 * bound to `@Param()` and `@Query()` parameters.
 *
 * When a handler is annotated with `@AggregateParamErrors()`, the `@Param()`
 * and `@Query()` parameter pipes are executed serially in parameter-index
 * order instead of concurrently. If one or more of those pipes reject, the
 * handler is skipped and a single {@link BadRequestException} is thrown whose
 * `message` is the array of the collected error messages (ordered by parameter
 * position). With a single error the response has the same shape as the
 * default validation error (`message` is a one-element array).
 *
 * Pipes bound to other parameter decorators (`@Body()`, custom decorators,
 * ...) and handlers without this decorator keep following the existing
 * execution path.
 *
 * @see [Pipes](https://docs.nestjs.com/pipes)
 *
 * @publicApi
 */
export function AggregateParamErrors(): MethodDecorator {
  return (
    target: object,
    key: string | symbol,
    descriptor: TypedPropertyDescriptor<any>,
  ) => {
    Reflect.defineMetadata(
      AGGREGATE_PARAM_ERRORS_METADATA,
      true,
      descriptor.value,
    );
    return descriptor;
  };
}

