  const calls: string[] = [];
  const slowPipe = (tag: string): PipeTransform => ({
    transform: async (value: unknown) => {
      calls.push(tag);
      await new Promise(resolve => setTimeout(resolve, 10));
      const parsed = Number(value);
      if (Number.isNaN(parsed)) {
        throw new BadRequestException(tag);
      }
      return parsed;
    },
  });
