  // one pipes function serves both concurrent "requests".
  const pipesFn = contextCreator.createPipesFn(
    [],
    [
      buildParamWithValue(
        0,
        RouteParamtypes.PARAM,
        (req: any) => req.id,
        [slowPipe('A')],
      ),
      buildParamWithValue(
        1,
        RouteParamtypes.QUERY,
        (req: any) => req.limit,
        [slowPipe('B')],
      ),
    ],
    true,
  )!;

